 p=by_slug[slug];items.append(dict(key=key,id=p['id'],title=p['title'],slug=slug,kind='Instagram Post',action='reuse-existing-approved',canonical='/ai-prompts/'+p['category_id']+'/'+slug,collections=['instagram-post-ideas','creative-transformations'],ratio='4:5',dimensions=[p['image_width'],p['image_height']],target_dimensions=[1080,1350],score=score,why_user=why,why_ai=p['why_ai'],visual_concept=p['description'],risk='Existing reviewed output; third-party personalization still requires reference testing. No guarantee of an identical face or result.',originality='Existing original PicMagic concept, not a new competitor adaptation; add collection membership only after approval, retaining its canonical URL.',reuse_asset=p['preview_image_url'],source_evidence=evidence,user_prompt=p['prompt_text'],preview_prompt=p['image_brief'],preview_persona='Existing fictional Indian persona documented in approved batch provenance; retain the image.',required_reference_assets=[],alt=p['image_alt'],related=[]))
