def add(key,title,slug,kind,mechanism,why,whyai,persona,risks,originality,evidence,art=False,existing=None,refs=None):
 p=by_slug.get(existing) if existing else None
 cat=p['category_id'] if p else 'social-media'
 framing=CIRCLE if kind=='Profile Picture' else POST
 prompt=(ART if art else PHOTO)+'\n\nCREATIVE DIRECTION: '+mechanism+'\n\n'+framing+'\n\nBefore rendering, resolve any conflict in favour of reference identity and the stated material. Identity preservation is an instruction, not a guaranteed third-party result.'
 preview=('Create a PicMagic fictional preview, not a personalized customer result. '+persona+'\n\n'+('Use the supplied approved fictional reference as the face authority; preserve its geometry and age cues while translating it to the declared medium. ' if refs else 'Use no real private person or competitor image as a reference. ')+mechanism+'\n\n'+framing+'\n\nNatural age cues and proportions; no airbrushed skin, ethnicity substitution, stereotyped features, anatomical distortion or watermark. This image is an AI-generated example.')
 if kind=='Instagram Post':prompt+='\n\nThis is an adult story/fashion concept. If the only reference is a child, ask for an appropriate adult reference rather than ageing the child up.'
 items.append(dict(key=key,id=p['id'] if p else str(uuid.uuid5(uuid.NAMESPACE_URL,'https://picmagic.in/planning/'+slug)),title=title,slug=slug,kind=kind,action='rework-existing-draft' if p else 'new-proposal',canonical='/ai-prompts/'+cat+'/'+slug,collections=['instagram-profile-picture'] if kind=='Profile Picture' else ['instagram-post-ideas','creative-transformations'],ratio='1:1' if kind=='Profile Picture' else '4:5',dimensions=[1024,1024] if kind=='Profile Picture' else [1080,1350],target_dimensions=[1024,1024] if kind=='Profile Picture' else [1080,1350],score=4,why_user=why,why_ai=whyai,visual_concept=mechanism,risk=risks,originality=originality,reuse_asset=None,source_evidence=evidence,user_prompt=prompt,preview_prompt=preview,preview_persona=persona,required_reference_assets=refs or [],alt=title+' — AI-generated '+('square portrait concept' if kind=='Profile Picture' else 'portrait-format concept')+'; replace this provisional alt text after the actual asset is inspected.',related=[]))
add('POST-04','Borrowed Moon, Closing Time','borrowed-moon-closing-time','Instagram Post',
 'Create one original fictional-film still in the side aisle of a small theatre after the performance. The person, waist-up in the foreground, steadies a lightweight moon-shaped theatre prop already resting on a low wheeled cart. Show a quiet amused sideways glance, as if caught returning the moon backstage. A crescent of the large painted prop remains beside the torso, never behind the head as a halo. Include one rolled stage curtain and softly receding empty seats; no famous film set, celebrity likeness or recognizable franchise costume. Warm work light grazes the face and painted surface; cooler spill from the stage gives depth. The moon is a tangible painted prop, not a second sky or a glowing object fused to the hands. Keep hands simple and naturally resting on its accessible rim.',
 'A playful fictional movie moment that feels like a story about the user, not a generic portrait.',
 'Recreates a controlled theatre shoot with a large scenic prop and coordinated set lighting that most people cannot readily stage.',
 'One fictional Indian man about 29, medium-brown complexion, shoulder-length naturally wavy hair, short beard, ordinary sturdy build, in a faded olive work jacket over a plain T-shirt.',
 'Medium: hand/prop contact and cart scale; reject distorted wrists, an apparent floating moon, or a face too small in the frame.',
 'The returning-a-prop action is original to this proposal. It does not reproduce the researched railway poster, typography, tiny travellers or miniature-lemon campaign. Unlike PicMagic’s existing cinema portrait, the prop-returning action carries the story.', ['YM05','CG05'])
add('POST-05','One Ribbon, a Whole Room','one-ribbon-a-whole-room','Instagram Post',
 'Create a fashion set made from one continuous broad terracotta fabric ribbon held on a believable concealed scenic support. It makes a sweeping freestanding loop behind one person and falls into a single fold across the floor. Photograph the person waist-up at the open side of that loop, face prominent, body slightly turned and one relaxed shoulder toward camera. The person wears a simple charcoal outfit distinct from the terracotta set; fabric does not emerge from their body or merge into their clothes. Broad soft light reveals real fabric weight, edges and cast shadows against a pale mineral wall. Keep the face evenly readable, with one sculptural fabric gesture as the entire set concept. If the user supplies a garment to advertise, retain its actual cut, colour and visible details; change only the surrounding scenic ribbon, not the product.',
 'Turn a personal fashion photograph into a striking physical campaign set without a busy fantasy background.',
 'Simulates a large fabricated set, specialist fabric rigging and coordinated studio production.',
 'One fictional Indian woman about 33, deep-brown complexion, long natural braids loosely gathered, ordinary broad-hipped build, wearing a modest charcoal jumpsuit with no branding.',
 'Medium: cloth may fuse with the subject or lose believable support; garment-reference use must not change the advertised design.',
 'One life-size scenic loop around a dominant face, not the existing Tailor’s Mountain Range textile landscape or the source’s miniature product-world storyboard.', ['CG06','CG05','YM08'])
add('DP-01','A Fold Around You','a-fold-around-you-profile','Profile Picture',
 'Create a photographic close portrait in front of a physically folded sheet of heavy cream paper. Two broad asymmetric folds behind the left and right shoulders form an open aperture around the head, with soft real cast shadows and a quiet petrol-blue backing. Keep the face, hair, glasses and clothing photographic; do not turn the person into paper, tear through the face or wrap paper around the neck. Use neutral soft frontal light on the face and restrained side light on the paper. Show one calm, natural expression with readable eyes and distinct separation from the backing.',
 'A clean avatar with a tactile frame that stays understandable at tiny size.',
 'Creates a custom folded set fitted precisely to a reference portrait and circular safe area.',
 'One fictional Indian man about 45, brown complexion, a receding hairline, close-cropped hair, rectangular glasses, short salt-and-pepper beard and a natural stocky build; plain navy crewneck.',
 'Low–medium: paper can intrude over hair or ears; frame contrast must not overpower glasses and eyes at 40px.',
 'The person remains photographic within a physical aperture. This is not PicMagic’s all-paper face or Canghe’s folded-paper landscape, and uses no source scene or props.', ['CG06'])
add('DP-02','A Small Burst of Motion','small-burst-of-motion-profile','Profile Picture',
 'Create a photographic chest-up avatar of one person in a relaxed slight turn, looking toward camera. Two broad hand-drawn brush arcs follow the outer shoulder line: one muted coral arc on one side and one deep teal arc on the other. They sit behind the shoulders like an illustrator’s notation of a lively turn, not extra arms, wings, a glowing halo or repeated silhouettes. Keep the head, facial landmarks and hair free of marks. Use a clean warm-grey ground, soft natural face light and one genuine small smile. The brushwork is visible pigment with imperfect edges; avoid confetti, symbols and many thin doodles.',
 'Express personality through one legible graphic gesture while keeping the face familiar.',
 'Combines a reference-conditioned photograph with carefully registered illustration adapted to a small avatar.',
 'One fictional Indian woman about 48, medium-deep complexion, salt-and-pepper bob with natural waves, small oval glasses and an ordinary full build; simple rust-coloured top.',
 'Medium: arcs can become extra limbs or clutter; expression adaptation must not alter eye shape or remove age cues.',
 'A single photographic face with two shoulder-level marks, not a before/after journal, repeated person sheet or PicMagic’s ink river transition.', ['AP01','CG03','YM08'])
add('DP-03','Monochrome Rain, Face in Focus','monochrome-rain-face-in-focus','Profile Picture',
 'Create a monochrome photographic portrait seen through a rain-speckled pane with a broad clear central viewing area. Keep eyes, nose, mouth, chin, hairline and identifying glasses fully clear and undistorted. Rain beads and soft vertical streaks occupy only the outer side bands and far background, disappearing behind a clean central face area rather than forming a conspicuous outlined circle. Use soft window light, rich midtones and a dark charcoal background with clear hair separation. Translate the source complexion into natural monochrome tonal relationships; do not lighten the face as a beauty treatment. Keep a composed natural expression. No water on the person’s face, split-face filter, artificial wet hair or neon colour.',
 'Keep a recognizable avatar while suggesting a quiet monsoon mood through the edge of the frame.',
 'Controls wet glass, depth, tonal contrast and a clean face zone specifically for circular cropping.',
 'One fictional Indian woman about 38 with deep-brown complexion represented by faithful monochrome tonal relationships, dense natural curls, a small visible cheek mark and an ordinary build; retain those distinguishing features, plain dark top.',
 'Medium: droplets or refraction may obscure eyes/glasses; monochrome must not flatten complexion into artificial whiteness. At 40px the face must work even if rain details disappear.',
 'Reworks the existing unpublished 4:5 rain concept into a purpose-built square avatar at its existing URL. No duplicate rain collection or canonical is introduced.', ['YM05','AP03'],art=True,existing='monochrome-rain-face-in-focus')
